// Stem a Snowball voc.txt (one word per line) with the Somali Snowball
// stemmer in js/snowball/, writing output.txt (one stem per line), the
// format snowball-data expects. The official file for the pull request is
// generated by Snowball's own `stemwords` program; this tool lets you
// produce and inspect the same output without building Snowball.
//
// With --compare, also reports how often Xidid's stemmer agrees.
//
// Usage:
//   node tools/stem-vocab.mjs voc.txt --out output.txt [--compare]

import fs from "node:fs";
import { writeText, args, snowballMapper, xididMapper } from "./lib.mjs";

const opt = args();
const input = opt._[0];
if (!input) {
  console.error("Usage: node tools/stem-vocab.mjs voc.txt --out output.txt [--compare]");
  process.exit(1);
}
const words = fs.readFileSync(input, "utf8").split("\n").map((w) => w.trim()).filter(Boolean);
// Snowball stems the word exactly as given (lower case expected), so call
// the generated stemmer directly rather than through Xidid's normaliser.
const { default: SomaliStemmer } = await import("../js/snowball/somali-stemmer.js");
const stemmer = new SomaliStemmer();
const stems = words.map((w) => stemmer.stemWord(w));
writeText(opt.out ?? "output.txt", stems.join("\n") + "\n");
const changed = stems.filter((s, i) => s !== words[i]).length;
console.log(`Stemmed ${words.length} words (${changed} changed) -> ${opt.out ?? "output.txt"}`);

if (opt.compare) {
  const x = xididMapper();
  const sbMap = snowballMapper();
  const groups = (f) => {
    const m = new Map();
    for (const w of words) {
      const s = f(w);
      if (!m.has(s)) m.set(s, 0);
      m.set(s, m.get(s) + 1);
    }
    return m.size;
  };
  const gx = groups(x), gs = groups(sbMap);
  console.log(`Distinct stems: Xidid ${gx} (${(100 * (1 - gx / words.length)).toFixed(1)}% reduction), Snowball ${gs} (${(100 * (1 - gs / words.length)).toFixed(1)}% reduction)`);
}
